// This file is @generated by perseid, vendored from the runtime of the CLI pack.
//! Printing responses: `--jq` first, then `--format`; paginated items stream through [`Items`].
//! Without `--format`: `table` on a terminal (or the CLI's `default_format`), else `json`
//! (`jsonl` for paginated items and event streams, which are `jsonl` on a terminal too). JSON is
//! compact off a terminal unless `--pretty`. `--jq` runs on each item of a list, or on the whole
//! array with `--format json`. Off a terminal nothing is colored or truncated; keys keep the
//! order of the SDK's models.
use std::{io::Write, rc::Rc};

use comfy_table::{Attribute, Cell, ContentArrangement, Table};
use serde::Serialize;
use serde_json::Value;

use super::{error::CliError, jq::Jq};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Format {
    Json,
    Jsonl,
    Yaml,
    Table,
}

impl Format {
    pub const NAMES: [&'static str; 4] = ["json", "jsonl", "yaml", "table"];

    pub fn parse(name: &str) -> Option<Self> {
        match name {
            "json" => Some(Self::Json),
            "jsonl" => Some(Self::Jsonl),
            "yaml" => Some(Self::Yaml),
            "table" => Some(Self::Table),
            _ => None,
        }
    }

    /// Its name, as `--format` takes it.
    pub fn name(self) -> &'static str {
        match self {
            Self::Json => "json",
            Self::Jsonl => "jsonl",
            Self::Yaml => "yaml",
            Self::Table => "table",
        }
    }

    /// Whether programs read it: errors are then JSON too.
    pub fn is_json(self) -> bool {
        matches!(self, Self::Json | Self::Jsonl)
    }
}

/// Longest cell on a terminal; longer ones end with `…`.
pub const MAX_CELL: usize = 48;

/// Narrower terminals get unwrapped tables rather than one-letter columns.
const MIN_WIDTH: u16 = 40;

/// How an [`Output`] prints.
#[derive(Clone, Copy, Debug, Default)]
pub struct Style {
    /// `None` picks the format by the rule in the module documentation.
    pub format: Option<Format>,
    /// The format without `format` on a terminal; `None` for `table`.
    pub tty_format: Option<Format>,
    /// stdout is a terminal: tables fit its width and truncate cells, JSON is indented.
    pub tty: bool,
    pub color: bool,
    /// Indent JSON off a terminal too.
    pub pretty: bool,
    /// Stop paginated output after this many items.
    pub max_items: Option<usize>,
    /// Fetch every page on a terminal too, where lists otherwise stop after the first page.
    pub all: bool,
    /// Table width on a terminal; `None` asks the terminal.
    pub width: Option<u16>,
}

impl Style {
    fn indent(self) -> bool {
        self.pretty || self.tty
    }
}

/// What a list printed, which `mcp` reads back instead of guessing from the output.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Listed {
    pub count: usize,
    /// Pages follow the one fetched.
    pub more: bool,
    /// The cursor of the page after the one fetched, from its response.
    pub cursor: Option<String>,
}

/// Where an [`Output`] reports its list.
pub type Report = Rc<std::cell::Cell<Option<Listed>>>;

/// stdout, with the format, filter and limits of the command line.
pub struct Output {
    out: Box<dyn Write>,
    style: Style,
    jq: Option<Jq>,
    hints: Option<Box<dyn Write>>,
    report: Option<Report>,
}

impl Output {
    pub fn new(out: Box<dyn Write>, style: Style, jq: Option<Jq>) -> Self {
        Self {
            out,
            style,
            jq,
            hints: None,
            report: None,
        }
    }

    #[must_use]
    pub fn with_report(mut self, report: Option<Report>) -> Self {
        self.report = report;
        self
    }

    /// Where hints for people go, such as how to fetch the pages a terminal did not show.
    #[must_use]
    pub fn with_hints(mut self, stderr: Box<dyn Write>) -> Self {
        self.hints = Some(stderr);
        self
    }

    pub fn style(&self) -> Style {
        self.style
    }

    /// Prints one response, e.g. `ctx.out.print(&thing)?` (any `Serialize`, or a `Value`).
    pub fn print<T: Serialize + ?Sized>(&mut self, value: &T) -> Result<(), CliError> {
        let value = serde_json::to_value(value)?;
        let format = self.style.format.unwrap_or(if self.style.tty {
            self.style.tty_format.unwrap_or(Format::Table)
        } else {
            Format::Json
        });
        self.document(value, format)
    }

    /// A sink for paginated items, printing them as they arrive when the format allows.
    pub fn items(&mut self) -> Items<'_> {
        let format = self.style.format.unwrap_or(if self.style.tty {
            self.style.tty_format.unwrap_or(Format::Table)
        } else {
            Format::Jsonl
        });
        self.sink(format)
    }

    /// A sink for the events of a stream: `jsonl` unless `--format` says otherwise.
    pub fn events(&mut self) -> Items<'_> {
        let format = self.style.format.unwrap_or(Format::Jsonl);
        let mut items = self.sink(format);
        items.paged = false;
        items
    }

    fn sink(&mut self, format: Format) -> Items<'_> {
        let mode = match (format, &self.jq) {
            (Format::Jsonl, _) => Mode::Lines,
            (Format::Json, None) => Mode::JsonArray,
            (Format::Json, Some(_)) => Mode::Slurp(Vec::new()),
            (format, _) => Mode::Buffer(Vec::new(), format),
        };
        Items {
            max: self.style.max_items,
            out: self,
            mode,
            count: 0,
            paged: true,
            more: false,
            chosen: false,
            cursor: None,
            done: false,
        }
    }

    /// The raw stream, for bodies that are not JSON (files, completion scripts).
    pub fn writer(&mut self) -> &mut dyn Write {
        &mut *self.out
    }

    fn document(&mut self, value: Value, format: Format) -> Result<(), CliError> {
        let text = match &self.jq {
            None => render(&value, format, self.style),
            Some(_) => render_outputs(self.filter(&value)?, format, self.style),
        };
        self.out.write_all(text.as_bytes())?;
        self.out.flush()?;
        Ok(())
    }

    /// `--jq` on `value`; when it fails, `value` is printed as is so a response is never lost.
    fn filter(&mut self, value: &Value) -> Result<Vec<Value>, CliError> {
        let Some(jq) = &self.jq else {
            return Ok(vec![value.clone()]);
        };
        jq.run(value).or_else(|error| {
            self.out.write_all((value.to_string() + "\n").as_bytes())?;
            self.out.flush()?;
            Err(CliError::output(format!(
                "{error}; the unfiltered response was printed"
            )))
        })
    }

    fn hint(&mut self, text: &str) {
        if let Some(hints) = &mut self.hints {
            let _ = writeln!(hints, "{text}");
        }
    }
}

enum Mode {
    Lines,
    JsonArray,
    /// `--format json` with `--jq`: the filter sees the whole array.
    Slurp(Vec<Value>),
    /// Items, or with `--jq` the outputs of each item, printed at the end.
    Buffer(Vec<Value>, Format),
}

/// Paginated output: generated code pushes items until [`push`](Self::push) returns `false`
/// (`--max-items` reached), then calls [`finish`](Self::finish). Dropped unfinished, e.g. when
/// a page fails, it still closes a JSON array.
#[must_use = "call finish() to print buffered items and close a JSON array"]
pub struct Items<'o> {
    out: &'o mut Output,
    mode: Mode,
    count: usize,
    max: Option<usize>,
    paged: bool,
    more: bool,
    chosen: bool,
    cursor: Option<String>,
    done: bool,
}

impl Items<'_> {
    /// Whether `--max-items` is reached: fetching more is pointless.
    pub fn is_full(&self) -> bool {
        self.max.is_some_and(|max| self.count >= max)
    }

    /// How many items were pushed.
    pub fn count(&self) -> usize {
        self.count
    }

    /// Whether to fetch the first page only: on a terminal, without `--all` or `--max-items`.
    pub fn first_page_only(&self) -> bool {
        let style = self.out.style;
        self.paged && style.tty && !style.all && style.max_items.is_none()
    }

    /// Records whether pages follow the one fetched, `chosen` when the command line named it:
    /// [`finish`](Self::finish) mentions the others only when it did not.
    pub fn fetched_page(&mut self, more: bool, chosen: bool) {
        self.more = more;
        self.chosen = chosen;
    }

    /// Records the cursor of the next page, which the page's `body` holds at `path` (the
    /// `next_cursor` of its pagination).
    pub fn next_cursor<B: Serialize + ?Sized>(&mut self, body: &B, path: &[&str]) {
        let body = serde_json::to_value(body).unwrap_or_default();
        let cursor = path.iter().try_fold(&body, |value, key| value.get(key));
        self.cursor = cursor.and_then(Value::as_str).map(str::to_owned);
    }

    /// Prints or buffers `item`; `Ok(false)` once no more items are wanted.
    pub fn push<T: Serialize + ?Sized>(&mut self, item: &T) -> Result<bool, CliError> {
        if self.is_full() {
            return Ok(false);
        }
        let value = serde_json::to_value(item)?;
        self.count += 1;
        let out = &mut *self.out;
        match &mut self.mode {
            Mode::Lines => {
                let text = match &out.jq {
                    None => render(&value, Format::Jsonl, out.style),
                    Some(_) => render_outputs(out.filter(&value)?, Format::Jsonl, out.style),
                };
                out.out.write_all(text.as_bytes())?;
                out.out.flush()?;
            }
            Mode::JsonArray => {
                let (open, separator) = if out.style.indent() {
                    ("[\n", ",\n")
                } else {
                    ("[", ",\n")
                };
                let text = match out.style.indent() {
                    true => indent(&serde_json::to_string_pretty(&value)?),
                    false => value.to_string(),
                };
                let separator = if self.count == 1 { open } else { separator };
                out.out.write_all(separator.as_bytes())?;
                out.out.write_all(text.as_bytes())?;
                out.out.flush()?;
            }
            Mode::Slurp(items) => items.push(value),
            Mode::Buffer(items, _) => match &out.jq {
                None => items.push(value),
                Some(_) => items.extend(out.filter(&value)?),
            },
        }
        Ok(!self.is_full())
    }

    /// Prints what was buffered, or closes the JSON array.
    pub fn finish(mut self) -> Result<(), CliError> {
        self.done = true;
        let end = self.close();
        let mode = std::mem::replace(&mut self.mode, Mode::Lines);
        let out = &mut *self.out;
        match mode {
            Mode::Lines => {}
            Mode::JsonArray => out.out.write_all(end.as_bytes())?,
            Mode::Slurp(items) => out.document(Value::Array(items), Format::Json)?,
            Mode::Buffer(items, Format::Table) if items.is_empty() => {
                if out.style.tty && out.jq.is_none() {
                    out.out.write_all(b"No results.\n")?;
                }
            }
            Mode::Buffer(items, format) if out.jq.is_some() => {
                let text = render_outputs(items, format, out.style);
                out.out.write_all(text.as_bytes())?;
            }
            Mode::Buffer(items, format) => out.document(Value::Array(items), format)?,
        }
        out.out.flush()?;
        if let Some(report) = &out.report {
            report.set(Some(Listed {
                count: self.count,
                more: self.more,
                cursor: self.cursor.take(),
            }));
        }
        if self.more && !self.chosen && self.first_page_only() {
            self.out.hint(&format!(
                "Showing the first {} items: --all fetches every page, --max-items N stops after N.",
                self.count
            ));
        }
        Ok(())
    }

    fn close(&self) -> &'static str {
        match (self.count, self.out.style.indent()) {
            (0, _) => "[]\n",
            (_, true) => "\n]\n",
            (_, false) => "]\n",
        }
    }
}

impl Drop for Items<'_> {
    fn drop(&mut self) {
        if !self.done && matches!(self.mode, Mode::JsonArray) {
            let end = self.close();
            let _ = self.out.out.write_all(end.as_bytes());
            let _ = self.out.out.flush();
        }
    }
}

fn indent(text: &str) -> String {
    text.lines()
        .map(|line| format!("  {line}"))
        .collect::<Vec<_>>()
        .join("\n")
}

/// One document in `format`, newline-terminated (empty for an empty `jsonl` array).
pub fn render(value: &Value, format: Format, style: Style) -> String {
    match format {
        Format::Json => json(value, style) + "\n",
        Format::Jsonl => match value {
            Value::Array(items) => items.iter().map(|item| item.to_string() + "\n").collect(),
            value => value.to_string() + "\n",
        },
        Format::Yaml => yaml(value),
        Format::Table => table(value, style),
    }
}

/// The outputs of `--jq`: strings raw (like `jq -r` and `gh --jq`), the rest in `format`.
pub fn render_outputs(outputs: Vec<Value>, format: Format, style: Style) -> String {
    if format == Format::Table && outputs.iter().all(|value| !value.is_string()) {
        return match <[Value; 1]>::try_from(outputs) {
            Ok([single]) => table(&single, style),
            Err(outputs) => table(&Value::Array(outputs), style),
        };
    }
    let separator = if format == Format::Yaml { "---\n" } else { "" };
    let rendered: Vec<String> = outputs
        .iter()
        .map(|value| match (value, format) {
            (Value::String(text), _) => text.clone() + "\n",
            (value, Format::Jsonl) => value.to_string() + "\n",
            (value, Format::Yaml) => yaml(value),
            (value, Format::Table) => table(value, style),
            (value, Format::Json) => json(value, style) + "\n",
        })
        .collect();
    rendered.join(separator)
}

fn json(value: &Value, style: Style) -> String {
    match style.indent() {
        true => pretty(value),
        false => value.to_string(),
    }
}

fn pretty(value: &Value) -> String {
    serde_json::to_string_pretty(value).unwrap_or_else(|_| value.to_string())
}

fn yaml(value: &Value) -> String {
    let text = serde_saphyr::to_string(value).unwrap_or_else(|_| pretty(value));
    if text.ends_with('\n') {
        text
    } else {
        text + "\n"
    }
}

/// Arrays of objects as rows, objects as key/value lines, anything else one value per line.
pub fn table(value: &Value, style: Style) -> String {
    match value {
        Value::Array(rows) if !rows.is_empty() && rows.iter().all(Value::is_object) => {
            let mut columns: Vec<&str> = Vec::new();
            for row in rows.iter().filter_map(Value::as_object) {
                for key in row.keys() {
                    if !columns.contains(&key.as_str()) {
                        columns.push(key);
                    }
                }
            }
            let mut table = new_table(style);
            table.set_header(columns.iter().map(|column| header(column, style)));
            for row in rows {
                table.add_row(
                    columns
                        .iter()
                        .map(|column| Cell::new(cell(row.get(*column), style))),
                );
            }
            lines(&table)
        }
        Value::Object(map) => {
            let mut table = new_table(style);
            for (key, value) in map {
                table.add_row([header(key, style), Cell::new(cell(Some(value), style))]);
            }
            lines(&table)
        }
        Value::Array(items) => items
            .iter()
            .map(|item| cell(Some(item), Style::default()) + "\n")
            .collect(),
        scalar => cell(Some(scalar), Style::default()) + "\n",
    }
}

fn new_table(style: Style) -> Table {
    let mut table = Table::new();
    table.load_style(comfy_table::presets::NOTHING);
    if style.tty {
        // A terminal reporting no usable width (e.g. under `script`) gets the natural layout.
        match style.width.or_else(|| table.width()) {
            Some(width) if width >= MIN_WIDTH => {
                table.set_width(width);
                table.set_content_arrangement(ContentArrangement::Dynamic);
            }
            _ => {
                table.set_content_arrangement(ContentArrangement::Disabled);
            }
        }
    } else {
        table.force_no_tty();
        table.set_content_arrangement(ContentArrangement::Disabled);
    }
    if style.color {
        table.enforce_styling();
    }
    table
}

fn header(name: &str, style: Style) -> Cell {
    let cell = Cell::new(name);
    if style.color {
        cell.add_attribute(Attribute::Bold)
    } else {
        cell
    }
}

fn lines(table: &Table) -> String {
    let mut table = table.clone();
    for column in table.column_iter_mut() {
        column.set_padding((0, 2));
    }
    table
        .lines()
        .map(|line| line.trim_end().to_owned() + "\n")
        .collect()
}

fn cell(value: Option<&Value>, style: Style) -> String {
    let text = match value {
        None | Some(Value::Null) => return String::new(),
        Some(Value::String(text)) => text.clone(),
        Some(other) => other.to_string(),
    };
    if !style.tty {
        return text;
    }
    let first_line = text.lines().next().unwrap_or_default();
    if first_line.chars().count() <= MAX_CELL && first_line.len() == text.len() {
        return text;
    }
    first_line.chars().take(MAX_CELL - 1).collect::<String>() + "…"
}

#[cfg(test)]
mod tests {
    use serde_json::json;

    use super::super::app::Buffer;
    use super::*;

    fn output(style: Style, jq: Option<&str>) -> (Output, Buffer) {
        let buffer = Buffer::default();
        let jq = jq.map(|code| Jq::compile(code).unwrap());
        (Output::new(Box::new(buffer.clone()), style, jq), buffer)
    }

    fn format(format: Format) -> Style {
        Style {
            format: Some(format),
            ..Style::default()
        }
    }

    fn things() -> Value {
        json!([
            {"id": "th_1", "name": "Widget", "price": 9.5, "tags": ["a"], "owner": null},
            {"id": "th_2", "name": "Gadget", "price": 12, "tags": [], "extra": {"k": true}}
        ])
    }

    fn printed(style: Style, jq: Option<&str>, value: &Value) -> String {
        let (mut out, buffer) = output(style, jq);
        out.print(value).unwrap();
        buffer.text()
    }

    fn streamed(style: Style, jq: Option<&str>, items: &[Value]) -> String {
        let (mut out, buffer) = output(style, jq);
        let mut sink = out.items();
        for item in items {
            if !sink.push(item).unwrap() {
                break;
            }
        }
        sink.finish().unwrap();
        buffer.text()
    }

    fn pretty(format: Format) -> Style {
        Style {
            format: Some(format),
            pretty: true,
            ..Style::default()
        }
    }

    #[test]
    fn json_is_compact_unless_pretty_and_keeps_key_order() {
        let value = json!({"z": 1, "a": [1, 2]});
        assert_eq!(
            printed(format(Format::Json), None, &value),
            "{\"z\":1,\"a\":[1,2]}\n"
        );
        assert_eq!(
            printed(pretty(Format::Json), None, &value),
            "{\n  \"z\": 1,\n  \"a\": [\n    1,\n    2\n  ]\n}\n"
        );
        let tty = Style {
            tty: true,
            ..format(Format::Json)
        };
        assert_eq!(
            printed(tty, None, &value),
            printed(pretty(Format::Json), None, &value)
        );
    }

    #[test]
    fn auto_format_is_json_off_a_terminal_and_a_table_on_one() {
        let value = json!({"id": "th_1"});
        assert_eq!(
            printed(Style::default(), None, &value),
            "{\"id\":\"th_1\"}\n"
        );
        let tty = Style {
            tty: true,
            width: Some(80),
            ..Style::default()
        };
        assert_eq!(printed(tty, None, &value), "id  th_1\n");
        assert_eq!(
            streamed(
                Style::default(),
                None,
                &[json!({"id": 1}), json!({"id": 2})]
            ),
            "{\"id\":1}\n{\"id\":2}\n"
        );
    }

    #[test]
    fn the_default_format_of_the_cli_replaces_tables_on_a_terminal_only() {
        let value = json!({"id": "th_1"});
        let yaml = Style {
            tty_format: Some(Format::Yaml),
            ..Style::default()
        };
        assert_eq!(printed(yaml, None, &value), "{\"id\":\"th_1\"}\n");
        let items = [json!({"id": 1}), json!({"id": 2})];
        assert_eq!(streamed(yaml, None, &items), "{\"id\":1}\n{\"id\":2}\n");
        let tty = Style { tty: true, ..yaml };
        assert_eq!(printed(tty, None, &value), "id: th_1\n");
        assert_eq!(streamed(tty, None, &items), "- id: 1\n- id: 2\n");
        let chosen = Style {
            format: Some(Format::Jsonl),
            ..tty
        };
        assert_eq!(printed(chosen, None, &value), "{\"id\":\"th_1\"}\n");
    }

    #[test]
    fn jsonl_prints_one_compact_document_per_line() {
        assert_eq!(
            printed(format(Format::Jsonl), None, &things()),
            concat!(
                r#"{"id":"th_1","name":"Widget","price":9.5,"tags":["a"],"owner":null}"#,
                "\n",
                r#"{"id":"th_2","name":"Gadget","price":12,"tags":[],"extra":{"k":true}}"#,
                "\n"
            )
        );
        assert_eq!(
            printed(format(Format::Jsonl), None, &json!({"a": 1})),
            "{\"a\":1}\n"
        );
    }

    #[test]
    fn yaml_documents() {
        assert_eq!(
            printed(
                format(Format::Yaml),
                None,
                &json!({"id": "th_1", "tags": ["a", "b"], "n": {"x": null}})
            ),
            "id: th_1\ntags:\n- a\n- b\n\"n\":\n  x: null\n"
        );
    }

    #[test]
    fn tables_take_columns_from_keys_in_order_of_appearance() {
        assert_eq!(
            printed(format(Format::Table), None, &things()),
            concat!(
                "id    name    price  tags   owner  extra\n",
                "th_1  Widget  9.5    [\"a\"]\n",
                "th_2  Gadget  12     []            {\"k\":true}\n",
            )
        );
    }

    #[test]
    fn objects_print_as_key_value_lines() {
        assert_eq!(
            printed(
                format(Format::Table),
                None,
                &json!({"id": "th_1", "meta": {"a": 1}, "none": null})
            ),
            "id    th_1\nmeta  {\"a\":1}\nnone\n"
        );
        assert_eq!(
            printed(format(Format::Table), None, &json!(["a", 1])),
            "a\n1\n"
        );
        assert_eq!(
            printed(format(Format::Table), None, &json!("plain")),
            "plain\n"
        );
    }

    #[test]
    fn cells_are_truncated_on_a_terminal_only() {
        let long = "x".repeat(60);
        let rows = json!([{"id": "th_1", "description": long, "note": "two\nlines"}]);
        let tty = Style {
            format: Some(Format::Table),
            tty: true,
            width: Some(200),
            ..Style::default()
        };
        let expected_cell = "x".repeat(MAX_CELL - 1) + "…";
        assert_eq!(
            printed(tty, None, &rows),
            format!(
                "id    description{}note\nth_1  {expected_cell}  two…\n",
                " ".repeat(MAX_CELL - 9)
            )
        );
        assert!(printed(format(Format::Table), None, &rows).contains(&long));
    }

    #[test]
    fn color_bolds_headers_on_a_terminal() {
        let style = Style {
            format: Some(Format::Table),
            tty: true,
            color: true,
            width: Some(80),
            ..Style::default()
        };
        let text = printed(style, None, &json!([{"id": 1}]));
        assert!(text.contains("\x1b[1m"), "{text:?}");
        assert!(!printed(format(Format::Table), None, &json!([{"id": 1}])).contains('\x1b'));
    }

    #[test]
    fn jq_runs_before_the_format_and_prints_strings_raw() {
        assert_eq!(
            printed(format(Format::Json), Some(".[].id"), &things()),
            "th_1\nth_2\n"
        );
        assert_eq!(
            printed(format(Format::Json), Some("map({id, price})"), &things()),
            "[{\"id\":\"th_1\",\"price\":9.5},{\"id\":\"th_2\",\"price\":12}]\n"
        );
        assert_eq!(
            printed(format(Format::Jsonl), Some(".[] | {id}"), &things()),
            "{\"id\":\"th_1\"}\n{\"id\":\"th_2\"}\n"
        );
        assert_eq!(
            printed(format(Format::Table), Some(".[] | {id, name}"), &things()),
            "id    name\nth_1  Widget\nth_2  Gadget\n"
        );
        assert_eq!(
            printed(format(Format::Yaml), Some(".[] | {id}"), &things()),
            "id: th_1\n---\nid: th_2\n"
        );
    }

    #[test]
    fn jsonl_streams_apply_jq_to_each_item() {
        let items = things().as_array().unwrap().clone();
        assert_eq!(
            streamed(format(Format::Jsonl), Some(".name"), &items),
            "Widget\nGadget\n"
        );
    }

    #[test]
    fn json_streams_print_one_array_and_jq_sees_all_of_it() {
        let items = things().as_array().unwrap().clone();
        assert_eq!(
            streamed(format(Format::Json), None, &[json!({"a": 1}), json!(2)]),
            "[{\"a\":1},\n2]\n"
        );
        assert_eq!(
            streamed(pretty(Format::Json), None, &[json!({"a": 1}), json!(2)]),
            "[\n  {\n    \"a\": 1\n  },\n  2\n]\n"
        );
        assert_eq!(streamed(format(Format::Json), None, &[]), "[]\n");
        assert_eq!(
            streamed(format(Format::Json), Some("length"), &items),
            "2\n"
        );
        assert_eq!(
            streamed(format(Format::Yaml), None, &items[..1])
                .lines()
                .next(),
            Some("- id: th_1")
        );
    }

    #[test]
    fn jq_runs_on_each_item_of_a_list_unless_the_format_is_json() {
        let items = things().as_array().unwrap().clone();
        let tty = Style {
            tty: true,
            width: Some(80),
            ..Style::default()
        };
        assert_eq!(streamed(tty, Some("{id}"), &items), "id\nth_1\nth_2\n");
        assert_eq!(streamed(tty, Some(".name"), &items), "Widget\nGadget\n");
        assert_eq!(
            streamed(Style::default(), Some(".name"), &items),
            streamed(tty, Some(".name"), &items)
        );
        assert_eq!(
            streamed(format(Format::Yaml), Some(".id"), &items),
            "th_1\n---\nth_2\n"
        );
        assert_eq!(
            streamed(format(Format::Json), Some("length"), &items),
            "2\n"
        );
    }

    #[test]
    fn events_are_lines_on_a_terminal_too() {
        let (mut out, buffer) = output(
            Style {
                tty: true,
                ..Style::default()
            },
            None,
        );
        let mut events = out.events();
        events.push(&json!({"a": 1})).unwrap();
        assert_eq!(buffer.text(), "{\"a\":1}\n");
        events.finish().unwrap();
    }

    #[test]
    fn unfinished_json_arrays_are_closed() {
        let (mut out, buffer) = output(format(Format::Json), None);
        let mut items = out.items();
        items.push(&json!(1)).unwrap();
        drop(items);
        assert_eq!(buffer.text(), "[1]\n");
    }

    #[test]
    fn failing_filters_print_the_response_unfiltered() {
        let (mut out, buffer) = output(Style::default(), Some(".a.b"));
        let error = out.print(&json!({"a": [1]})).unwrap_err();
        assert_eq!(error.exit_code(), super::super::error::exit::OUTPUT);
        assert!(
            error
                .message()
                .ends_with("the unfiltered response was printed"),
            "{error}"
        );
        assert_eq!(buffer.text(), "{\"a\":[1]}\n");
    }

    #[test]
    fn terminals_show_the_first_page_and_say_how_to_see_all() {
        let hints = Buffer::default();
        let tty = Style {
            tty: true,
            width: Some(80),
            ..Style::default()
        };
        let mut out =
            Output::new(Box::new(Buffer::default()), tty, None).with_hints(Box::new(hints.clone()));
        let mut items = out.items();
        assert!(items.first_page_only());
        items.push(&json!({"id": 1})).unwrap();
        items.fetched_page(true, false);
        items.finish().unwrap();
        assert!(
            hints.text().starts_with("Showing the first 1 items: --all"),
            "{}",
            hints.text()
        );
        let all = Style { all: true, ..tty };
        let (mut out, _) = output(all, None);
        assert!(!out.items().first_page_only());
        let (mut out, _) = output(Style::default(), None);
        assert!(!out.items().first_page_only());
    }

    #[test]
    fn max_items_stops_the_stream() {
        let style = Style {
            format: Some(Format::Jsonl),
            max_items: Some(2),
            ..Style::default()
        };
        let (mut out, buffer) = output(style, None);
        let mut sink = out.items();
        assert!(sink.push(&json!(1)).unwrap());
        assert!(!sink.push(&json!(2)).unwrap());
        assert!(sink.is_full());
        assert!(!sink.push(&json!(3)).unwrap());
        assert_eq!(sink.count(), 2);
        sink.finish().unwrap();
        assert_eq!(buffer.text(), "1\n2\n");
    }

    #[test]
    fn empty_tables_say_so_on_a_terminal_only() {
        let tty = Style {
            format: Some(Format::Table),
            tty: true,
            ..Style::default()
        };
        assert_eq!(streamed(tty, None, &[]), "No results.\n");
        assert_eq!(streamed(format(Format::Table), None, &[]), "");
    }
}
